for(const c of db.clients){c.imports??=[];c.products??=[];c.menuImages??=[];c.instagramImages??=[];c.contentPosts??=[];c.plan??=[];c.adAccounts??=[];c.logo??='';c.brandName??=c.name;c.instagram??='';c.site??='';c.status??='Ativo';c.observations??='';c.onboarding=typeof c.onboarding==='object'&&c.onboarding?c.onboarding:{notes:typeof c.onboarding==='string'?c.onboarding:''}; for(const p of c.products){p.quantity ??= p.orders ?? 0;p.revenue ??= num(p.price)*num(p.quantity);}}
const save = () => fs.writeFileSync(DATA, JSON.stringify(db,null,2));
