const cookieValue=(req,name)=>{const raw=req.headers.cookie||'';return raw.split(';').map(x=>x.trim()).find(x=>x.startsWith(name+'='))?.slice(name.length+1);};
function loginPage(message=''){return page('Entrar','',`<section class="card" style="max-width:440px;margin:12vh auto"><div class="eyebrow">ACESSO INTERNO DECOLA</div><h2>Entrar no Sistema Decola</h2><p class="sub">Este ambiente está protegido pelo código configurado na hospedagem.</p>${message?`<div class="notice" style="border-color:#d45c79">${esc(message)}</div>`:''}<form method="post" action="/login"><div class="field"><label>Código de acesso</label><input required name="code" type="password" autocomplete="current-password"></div><button class="btn">Entrar</button></form></section>`);}
