const css = `<style>:root{--bg:#100916;--panel:#1c1327;--line:#442c5d;--ink:#fbf8ff;--muted:#b8afc6;--p:#9869ff;--g:#6de0ac;--y:#ffd36c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,#46217a,transparent 30%),var(--bg);color:var(--ink);font:14px Inter,Arial,sans-serif}.shell{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{padding:26px 14px;border-right:1px solid var(--line);background:#120b1a}.brand{font-weight:800;letter-spacing:.13em;margin:0 10px 35px}.brand small{display:block;color:var(--muted);font-size:9px;margin-top:4px}.nav a{display:block;color:var(--muted);text-decoration:none;padding:11px;border-radius:8px;margin:4px 0}.nav a.on,.nav a:hover{background:#34204f;color:#fff;border-left:2px solid var(--p)}main{padding:30px;max-width:1400px;width:100%;margin:auto}.eyebrow{color:#cbb6ff;font-size:10px;font-weight:bold;letter-spacing:.14em}.head{display:flex;justify-content:space-between;gap:18px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:22px}.head h1{font-size:27px;margin:7px 0 0}.sub{color:var(--muted);font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:18px}.two{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.card{background:rgba(28,19,39,.94);border:1px solid var(--line);border-radius:13px;padding:18px}.label{color:var(--muted);font-weight:bold;letter-spacing:.1em;font-size:9px}.big{font-size:26px;font-weight:bold;margin:12px 0 4px}.up{color:var(--g);font-size:11px}.tag{background:#4b2c70;color:#e3d9ff;border-radius:99px;padding:5px 8px;font-size:10px}.tabs{display:flex;gap:5px;overflow:auto;margin:16px 0}.tabs a{white-space:nowrap;color:var(--muted);text-decoration:none;border:1px solid var(--line);border-radius:8px;padding:8px 10px;font-size:11px}.tabs a.on{background:#442765;color:#fff}.btn{border:0;background:linear-gradient(135deg,#a677ff,#7042dc);color:#fff;border-radius:8px;padding:10px 13px;font-weight:bold;text-decoration:none;display:inline-block}.field{display:grid;gap:6px;margin:11px 0}.field input,.field select,.field textarea{background:#100916;color:#fff;border:1px solid var(--line);border-radius:8px;padding:10px;width:100%}.field textarea{min-height:105px}table{width:100%;border-collapse:collapse;font-size:11px}th{text-align:left;color:var(--muted);padding:0 7px 10px}td{padding:10px 7px;border-top:1px solid var(--line)}.item{padding:11px 0;border-top:1px solid var(--line)}.item b{font-size:12px}.item small{color:var(--muted);display:block;margin-top:4px}.notice{padding:13px;border-left:2px solid var(--p);background:#281b37;border-radius:0 8px 8px 0;color:#ded5e8;font-size:12px;line-height:1.5}.empty{padding:26px;color:var(--muted);text-align:center}@media(max-width:800px){.shell{grid-template-columns:1fr}.side{border:0}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.grid,.two{grid-template-columns:1fr 1fr}main{padding:20px}}@media(max-width:500px){.grid,.two{grid-template-columns:1fr}.head{display:block}}</style>`;
function nav(on){const item=(href,label,key)=>`<a class="${on===key?'on':''}" href="${href}">${label}</a>`;return `<aside class="side"><div class="brand">DECOLA<small>SISTEMA 1.0</small></div><nav class="nav">${item('/','Visão geral','home')}${item('/clientes','Clientes','clients')}${item('/importar','Importar dados','import')}${item('/cardapio','🍽️ Cardápio','menu')}${item('/conteudo','🎬 Conteúdo','content')}${item('/instagram','Instagram','instagram')}${item('/diagnostico','Diagnóstico 360°','diag')}${item('/plano','Plano de Decolagem','plan')}</nav><div class="nav-label">CENTRAL DE TRÁFEGO</div><nav class="nav">${item('/campanhas','Campanhas','campaigns')}${item('/criativos','Criativos','creatives')}${item('/monitoramento','Monitoramento','monitor')}${item('/automacoes','Automações','automations')}${item('/configuracoes','Configurações','settings')}</nav>${authEnabled()?`<nav class="nav"><a href="/sair">Sair</a></nav>`:''}</aside>`;}
function page(title,on,body){return `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · Sistema Decola</title>${css}<div class="shell">${nav(on)}<main><header class="head"><div><div class="eyebrow">INTELIGÊNCIA OPERACIONAL</div><h1>${esc(title)}</h1></div><span class="tag">MVP interno</span></header>${body}</main></div>`;}
function tabs(c,active){return `<div class="tabs"><a class="${active==='client'?'on':''}" href="/clientes/${c.id}">Visão geral</a><a class="${active==='onboarding'?'on':''}" href="/clientes/${c.id}/onboarding">Onboarding</a><a class="${active==='menu'?'on':''}" href="/cardapio?client=${c.id}">Cardápio</a><a class="${active==='instagram'?'on':''}" href="/instagram?client=${c.id}">Instagram</a><a href="/diagnostico?client=${c.id}">Diagnóstico</a><a href="/plano?client=${c.id}">Plano</a></div>`;}
function getActive(q){return client(q.get('client'))||db.clients[0];}
function noClientPage(title){return page(title,'clients',`<section class="card"><h2>Crie o primeiro cliente</h2><p class="sub">Você ainda não possui restaurantes na base. Ao criar um cliente, poderá adicionar onboarding, dados, fotos, diagnóstico e plano de ação.</p><a class="btn" href="/clientes/novo">+ Adicionar cliente</a></section>`);}
function home(query){
  const selected=query?.get('client')||'all'; const scope=selected==='all'?db.clients:db.clients.filter(c=>c.id===selected); const summaries=scope.map(c=>({c,m:metrics(c)}));
  const revenue=summaries.reduce((a,x)=>a+x.m.revenue,0), orders=summaries.reduce((a,x)=>a+x.m.orders,0), products=summaries.reduce((a,x)=>a+x.m.p.length,0), imports=summaries.reduce((a,x)=>a+x.c.imports.length,0), ticket=orders?revenue/orders:0;
  const ranked=[...summaries].sort((a,b)=>b.m.revenue-a.m.revenue); const max=Math.max(1,...ranked.map(x=>x.m.revenue)); const attention=summaries.filter(x=>!x.c.imports.length||!x.c.onboarding?.notes);
  const onboardingReady=summaries.filter(x=>x.c.onboarding?.notes).length, importedReady=summaries.filter(x=>x.c.imports.length).length, costReady=summaries.filter(x=>x.m.p.some(p=>p.cost!=null)).length;
  const planActions=summaries.reduce((a,x)=>a+(x.c.plan?.length||0),0), planDone=summaries.reduce((a,x)=>a+(x.c.plan||[]).filter(p=>p.done).length,0), visualEvidence=summaries.reduce((a,x)=>a+(x.c.menuImages?.length||0)+(x.c.instagramImages?.length||0),0);
  const selector=`<form class="dash-filter" method="get" action="/"><label>VISÃO</label><select name="client" onchange="this.form.submit()"><option value="all" ${selected==='all'?'selected':''}>Todos os clientes</option>${db.clients.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span>Base: dados importados</span></form>`;
  const bars=ranked.map(x=>`<div class="bar-row"><div><b>${esc(x.c.name)}</b><small>${esc(x.c.segment)}</small></div><div class="bar-track"><span style="width:${Math.max(3,Math.round(x.m.revenue/max*100))}%"></span></div><strong>${x.m.revenue?money(x.m.revenue):'—'}</strong></div>`).join('')||'<p class="sub">Adicione clientes para acompanhar a agência.</p>';
  const table=ranked.map(x=>`<tr><td><a href="/clientes/${x.c.id}"><b>${esc(x.c.name)}</b></a><small>${esc(x.c.segment)} · ${esc(x.c.city)}</small></td><td>${x.m.revenue?money(x.m.revenue):'—'}</td><td>${x.m.orders||'—'}</td><td>${x.m.orders?money(x.m.ticket):'—'}</td><td>${x.c.imports.length||'—'}</td><td>${x.c.menuImages?.length||'—'}</td><td>${x.c.instagramImages?.length||'—'}</td><td><a class="table-link" href="/diagnostico?client=${x.c.id}">Abrir</a></td></tr>`).join('');
  return page('Visão geral','home',`<style>.dash-head{display:flex;align-items:end;justify-content:space-between;gap:18px;margin:16px 0}.dash-actions{display:flex;gap:8px;align-items:end}.dash-filter{display:flex;align-items:end;gap:8px;background:#1a1126;border:1px solid var(--line);padding:9px 11px;border-radius:10px}.dash-filter label{font-size:9px;color:var(--muted);font-weight:bold;letter-spacing:.1em}.dash-filter select{background:#100916;color:#fff;border:0;outline:0}.dash-filter span{font-size:10px;color:var(--muted);border-left:1px solid var(--line);padding-left:8px}.dash-kpis{grid-template-columns:repeat(5,1fr)}.dash-kpis .card{padding:16px}.dash-kpis .big{font-size:23px}.perf-grid{grid-template-columns:repeat(4,1fr);margin-top:14px}.perf-grid .card{padding:15px}.dash-main{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.bar-row{display:grid;grid-template-columns:125px 1fr 100px;align-items:center;gap:10px;padding:11px 0;border-top:1px solid var(--line);font-size:11px}.bar-row small,.dash-table small{display:block;color:var(--muted);margin-top:2px}.bar-track{height:7px;border-radius:20px;background:#100916;overflow:hidden}.bar-track span{height:100%;display:block;background:linear-gradient(90deg,#8051ea,#be9aff);border-radius:20px}.attention{border-left:3px solid var(--y)}.attention strong{display:block;font-size:12px}.dash-table a{color:#ece4ff;text-decoration:none}.dash-table .table-link{color:#bb9aff;font-weight:bold}.dash-table td{vertical-align:top}@media(max-width:900px){.dash-kpis,.perf-grid{grid-template-columns:repeat(2,1fr)}.dash-main{grid-template-columns:1fr}.dash-head{align-items:start;display:block}.dash-actions{margin-top:12px;align-items:center}.dash-filter{width:max-content}.bar-row{grid-template-columns:100px 1fr 80px}}</style><div class="dash-head"><div><div class="eyebrow">RESULTADOS & CRESCIMENTO</div><h2 style="margin:6px 0">Decola Analytics</h2><p class="sub">Uma visão clara dos resultados que orientam as decisões da agência.</p></div><div class="dash-actions">${selector}<a class="btn" href="/clientes/novo">+ Adicionar cliente</a></div></div><section class="grid dash-kpis"><div class="card"><div class="label">FATURAMENTO</div><div class="big">${revenue?money(revenue):'—'}</div><small class="sub">Base disponível</small></div><div class="card"><div class="label">ITENS VENDIDOS</div><div class="big">${orders||'—'}</div><small class="sub">Base disponível</small></div><div class="card"><div class="label">TICKET MÉDIO</div><div class="big">${orders?money(ticket):'—'}</div><small class="sub">Base disponível</small></div><div class="card"><div class="label">CLIENTES</div><div class="big">${scope.length}</div><small class="sub">No filtro atual</small></div><div class="card"><div class="label">PRODUTOS</div><div class="big">${products||'—'}</div><small class="sub">${imports} importação(ões)</small></div></section><section class="grid perf-grid"><div class="card"><div class="label">BASE ESTRUTURADA</div><div class="big">${scope.length?Math.round((onboardingReady+importedReady)/(scope.length*2)*100):0}%</div><small class="sub">Onboarding e dados enviados</small></div><div class="card"><div class="label">MARGEM DISPONÍVEL</div><div class="big">${costReady}/${scope.length}</div><small class="sub">Clientes com algum custo informado</small></div><div class="card"><div class="label">EXECUÇÃO DO PLANO</div><div class="big">${planActions?Math.round(planDone/planActions*100)+'%':'—'}</div><small class="sub">${planDone}/${planActions} ação(ões) concluída(s)</small></div><div class="card"><div class="label">EVIDÊNCIAS VISUAIS</div><div class="big">${visualEvidence||'—'}</div><small class="sub">Fotos de cardápio e prints de Instagram</small></div></section><section class="dash-main"><div class="card"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Performance da agência</h2><span class="tag">Faturamento</span></div><p class="sub">Participação por cliente conforme os dados disponíveis.</p>${bars}</div><div class="card attention"><h2>Precisam de atenção</h2>${attention.length?attention.map(x=>`<div class="item"><strong>${esc(x.c.name)}</strong><small>${!x.c.imports.length?'Ainda não possui importação de dados.':'Onboarding ainda não foi registrado.'}</small><a class="table-link" href="/clientes/${x.c.id}">Abrir cliente</a></div>`).join(''):'<p class="sub">Nenhum alerta básico no filtro atual.</p>'}</div></section><section class="card" style="margin-top:14px"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Performance dos clientes</h2><span class="tag">${scope.length} cliente(s)</span></div><div class="scroll"><table class="dash-table"><thead><tr><th>Cliente</th><th>Faturamento</th><th>Itens</th><th>Ticket</th><th>Importações</th><th>Fotos</th><th>Instagram</th><th>Diagnóstico</th></tr></thead><tbody>${table||'<tr><td colspan="8">Nenhum cliente neste filtro.</td></tr>'}</tbody></table></div></section><section class="two"><div class="card"><h2>Fluxo Decola</h2><div class="notice">Cliente → onboarding → importações → Cardápio/Instagram → Diagnóstico 360° → Plano de ação.</div></div><div class="card"><h2>Próximo passo</h2><p class="sub">Use “Adicionar dados” dentro de um cliente para alimentar os indicadores deste dashboard.</p><a class="btn" href="/clientes">Gerenciar clientes</a></div></section>`);
}
function clients(){return page('Clientes','clients',`<p><a class="btn" href="/clientes/novo">+ Novo cliente</a></p><section class="grid">${db.clients.map(c=>`<a class="card" style="color:inherit;text-decoration:none" href="/clientes/${c.id}"><b>${esc(c.name)}</b><p class="sub">${esc(c.segment)} · ${esc(c.city)}, ${esc(c.state)}</p><span class="tag">${c.imports.length} arquivo(s)</span></a>`).join('')||'<div class="card"><p class="sub">Nenhum cliente cadastrado.</p></div>'}</section>`);}
function clientPage(c){const accounts=(c.adAccounts||[]).map(a=>`<div class="item"><b>${esc(a.name)}</b><small>${esc(a.platform)} · ID ${esc(a.accountId)} · ${esc(a.connectionStatus)}</small></div>`).join('');return page(c.name,'clients',`${tabs(c,'client')}<section class="two"><div class="card"><h2>Negócio</h2><div class="item"><b>Cliente desde</b><small>${esc(c.startedAt)}</small></div><div class="item"><b>Objetivo</b><small>${esc(c.goal||'Não informado')}</small></div><div class="item"><b>Responsável</b><small>${esc(c.owner)}</small></div><div class="item"><b>Status</b><small>${esc(c.status)}</small></div></div><div class="card"><h2>Próxima ação</h2><div class="notice">Envie vendas, custos ou cardápio. O sistema aponta o que já consegue analisar e as limitações.</div><p><a class="btn" href="/importar?client=${c.id}">Importar dados</a></p></div></section><section class="two"><div class="card"><h2>Contas de anúncios</h2><p class="sub">Apenas o vínculo da conta é armazenado. Senhas da Meta nunca entram no sistema.</p>${accounts||'<p class="sub">Nenhuma conta cadastrada.</p>'}<hr><form method="post" action="/clientes/${c.id}/contas"><div class="field"><label>Plataforma</label><select name="platform"><option>Meta</option><option disabled>Google (futuro)</option><option disabled>TikTok (futuro)</option></select></div><div class="field"><label>ID da conta</label><input name="accountId" required placeholder="act_123..."></div><div class="field"><label>Nome da conta</label><input name="accountName" required></div><button class="btn">Vincular conta</button></form></div><div class="card"><h2>Dados de contato</h2><div class="item"><b>Instagram</b><small>${esc(c.instagram||'Não informado')}</small></div><div class="item"><b>Site</b><small>${esc(c.site||'Não informado')}</small></div><div class="item"><b>Observações</b><small>${esc(c.observations||'Não informado')}</small></div></div></section><section class="card" style="margin-top:14px;border-color:#7e3a59"><h2>Administração do cliente</h2><p class="sub">A exclusão remove os arquivos, análises, imagens, contas e plano de ação vinculados a este restaurante.</p><form method="post" action="/clientes/${c.id}/excluir" onsubmit="return confirm('Excluir ${esc(c.name)} e todos os dados vinculados? Esta ação não poderá ser desfeita.');"><button class="btn" style="background:#a83e63">Excluir cliente</button></form></section>`);}
function newClient(){return page('Novo cliente','clients',`<section class="card"><form method="post" action="/clientes"><div class="field"><label>Nome</label><input required name="name"></div><div class="field"><label>Nome fantasia</label><input name="brandName"></div><div class="field"><label>Segmento</label><input required name="segment"></div><div class="two"><div class="field"><label>Cidade</label><input required name="city"></div><div class="field"><label>Estado</label><input required name="state"></div></div><div class="two"><div class="field"><label>Instagram</label><input name="instagram" placeholder="@cliente"></div><div class="field"><label>Site</label><input name="site" type="url"></div></div><div class="field"><label>Cliente desde</label><input required type="date" name="startedAt"></div><div class="field"><label>Objetivo</label><textarea name="goal"></textarea></div><div class="field"><label>Observações</label><textarea name="observations"></textarea></div><button class="btn">Criar cliente</button></form></section>`);}

function metrics(c){
  const p=c.products||[]; const revenue=p.reduce((a,x)=>a+(+x.revenue||0),0); const orders=p.reduce((a,x)=>a+(+x.quantity||x.orders||0),0);
  const margin=p.reduce((a,x)=>a+(x.cost==null?0:((+x.price||0)-(+x.cost||0))*(+x.quantity||0)),0);
  const withCost=p.filter(x=>x.cost!=null).length; const avgMargin=withCost?margin/revenue: null;
  const ranked=[...p].sort((a,b)=>(b.revenue||0)-(a.revenue||0));
  const hero=[...p].sort((a,b)=>((b.revenue||0)+(b.margin||0)*100)-((a.revenue||0)+(a.margin||0)*100))[0];
  return {p,revenue,orders,margin,avgMargin,ranked,hero,ticket:orders?revenue/orders:0};
}
function num(v){return Number.isFinite(+v)?+v:0;}
function dataMessage(c){return c.products.length?`<div class="notice ok">Dados disponíveis: ${c.products.length} produto(s) agregados a partir das importações e cadastros deste cliente.</div>`:`<div class="notice">Ainda não há dados de produto. Importe uma planilha de vendas/produtos ou cadastre informações do cardápio.</div>`;}
function onboardingPage(c){const o=c.onboarding||{};return page(`Onboarding · ${c.name}`,'clients',`${tabs(c,'onboarding')}<section class="two"><div class="card"><h2>Briefing estratégico</h2><p class="sub">Registre a transcrição, resumo ou notas da conversa humana. O conteúdo fica vinculado somente a este restaurante.</p><form method="post" enctype="multipart/form-data" action="/clientes/${c.id}/onboarding"><div class="field"><label>Transcrição, resumo ou notas</label><textarea name="notes" placeholder="Cole aqui a transcrição ou os principais pontos da reunião.">${esc(o.notes||'')}</textarea></div><div class="field"><label>Anexar documento</label><input type="file" name="document" accept=".txt,.doc,.docx,.pdf"><small>O arquivo é preservado no histórico. A leitura automática de DOC/DOCX/PDF exige uma integração de IA/documentos, que não está configurada neste MVP.</small></div><button class="btn">Salvar onboarding</button></form></div><div class="card"><h2>O que a Decola registra</h2><div class="item"><b>Fato informado</b><small>História, objetivo, público, região, produtos, desafios e expectativas.</small></div><div class="item"><b>Inferência</b><small>Só deve aparecer separada dos fatos após uma análise com dados suficientes.</small></div>${o.document?`<div class="notice ok">Documento anexado: ${esc(o.document.name)}</div>`:''}</div></section>`);}
function importPage(c){return page(`Importar dados · ${c.name}`,'import',`${tabs(c,'data')}<section class="two"><div class="card"><h2>Adicionar dados ao restaurante</h2><p class="sub">CSV e XLSX são lidos, mapeados e só entram no diagnóstico após sua confirmação. XLS/PDF ficam registrados como fonte para revisão manual.</p><form method="post" enctype="multipart/form-data" action="/importar"><input type="hidden" name="client" value="${c.id}"><div class="field"><label>Tipo de relatório</label><select name="type"><option>Vendas</option><option>Produtos</option><option>Clientes</option><option>Cardápio</option><option>Tráfego</option></select></div><div class="field"><label>Período de referência</label><input name="period" placeholder="Ex.: Agosto/2026"></div><div class="field"><label>Arquivo</label><input required type="file" name="file" accept=".csv,.xlsx,.xls,.pdf"></div><button class="btn">Identificar campos</button></form></div><div class="card"><h2>Arquivos já enviados</h2>${c.imports.length?c.imports.map(x=>`<div class="item"><b>${esc(x.name)}</b><small>${esc(x.type)} · ${esc(x.period||'Período não informado')} · ${esc(x.status)}</small></div>`).join(''):`<p class="sub">Nenhum arquivo enviado.</p>`}</div></section>`);}
function importConfirm(token){const p=pendingImports.get(token);if(!p)return page('Importação expirada','import','<section class="card"><p>Esta prévia expirou. Envie o arquivo novamente.</p><a class="btn" href="/importar">Voltar para importação</a></section>');const c=client(p.clientId);const options=[['IGNORE','Ignorar'],['PRODUCT_NAME','Produto'],['CATEGORY','Categoria'],['QUANTITY','Quantidade'],['PRICE','Preço unitário'],['COST','Custo unitário'],['REVENUE','Faturamento/valor total']];const rows=p.headers.map((h,i)=>`<tr><td><b>${esc(h)}</b></td><td><select name="m_${i}">${options.map(([v,l])=>`<option value="${v}" ${p.map[i]===v?'selected':''}>${l}</option>`).join('')}</select></td><td>${esc(p.preview.map(r=>r[h]).filter(v=>v).slice(0,2).join(' · ')||'—')}</td></tr>`).join('');return page(`Confirmar importação · ${c?.name||''}`,'import',`<section class="card"><h2>Confirme a leitura dos campos</h2><p class="sub">Arquivo: ${esc(p.name)} · ${p.rows.length} linhas encontradas. Ajuste campos ambíguos antes de salvar.</p><form method="post" action="/importar/confirmar"><input type="hidden" name="token" value="${token}"><div class="scroll"><table><thead><tr><th>Campo do arquivo</th><th>Dado Decola</th><th>Prévia</th></tr></thead><tbody>${rows}</tbody></table></div><p><button class="btn">Confirmar e salvar dados</button></p></form></section>`);}
function productForm(c){return `<details class="card"><summary><b>+ Adicionar ou corrigir produto manualmente</b></summary><form method="post" action="/clientes/${c.id}/produtos"><div class="field"><label>Produto</label><input name="name" required></div><div class="field"><label>Categoria</label><input name="category" placeholder="Ex.: Hambúrgueres"></div><div class="field"><label>Quantidade vendida</label><input name="quantity" type="number" min="0"></div><div class="field"><label>Preço médio (R$)</label><input name="price" type="number" step="0.01" min="0"></div><div class="field"><label>Custo unitário (R$)</label><input name="cost" type="number" step="0.01" min="0"></div><button class="btn">Salvar produto</button></form></details>`;}
function menuTabs(){return `<div class="tabs"><a href="#visao">Visão geral</a><a href="#produtos">Produtos</a><a href="#categorias">Categorias</a><a href="#engenharia">Engenharia</a><a href="#margens">Preços & margens</a><a href="#combos">Combos & upsell</a><a href="#conversao">Conversão</a><a href="#oportunidades">Oportunidades</a><a href="#historico">Histórico</a></div>`;}
function menuPage(c){const m=metrics(c), h=m.hero; const rows=m.ranked.map(x=>{const mg=x.cost==null?null:(x.price-x.cost)/x.price;const pop=m.orders?x.quantity/m.orders:0;const cl=mg==null?'N/D':pop>=.15?(mg>=.45?'⭐ Estrela':'🐎 Cavalo de batalha'):(mg>=.45?'🧩 Quebra-cabeça':'⚪ Baixa performance');return `<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.category||'N/D')}</td><td>${x.quantity||0}</td><td>${money(x.revenue||0)}</td><td>${x.price?money(x.price):'N/D'}</td><td>${x.cost==null?'N/D':money(x.cost)}</td><td>${mg==null?'N/D':(mg*100).toFixed(0)+'%'}</td><td>${cl}</td></tr>`;}).join('');const categories=[...new Set(m.p.map(x=>x.category).filter(Boolean))];return page(`Cardápio · ${c.name}`,'menu',`${tabs(c,'menu')}${menuTabs()}<div id="visao">${dataMessage(c)}</div><div class="filter"><span>Período: todos os dados importados</span><span>Canal: N/D</span><span>Categoria: todas</span></div><section class="grid"><div class="card"><div class="label">FATURAMENTO</div><div class="big">${money(m.revenue)}</div></div><div class="card"><div class="label">ITENS VENDIDOS</div><div class="big">${m.orders}</div></div><div class="card"><div class="label">TICKET MÉDIO POR ITEM</div><div class="big">${money(m.ticket)}</div></div><div class="card"><div class="label">MARGEM MÉDIA</div><div class="big">${m.avgMargin==null?'N/D':(m.avgMargin*100).toFixed(0)+'%'}</div></div></section><section class="two"><div class="card"><h2>Produto-herói Decola</h2>${h?`<h3>${esc(h.name)}</h3><p>${h.quantity||0} itens · ${money(h.revenue||0)} em receita.</p><div class="notice">Prévia baseada em volume e faturamento disponíveis. Margem, foto e exposição em conteúdo refinam a avaliação.</div>`:'<p class="sub">Envie dados de vendas e custos para identificar um candidato.</p>'}</div><div class="card"><h2>O que a Decola faria agora?</h2>${m.p.length?`<div class="item"><b>01 — Validar margem do produto campeão</b><small>Antes de escalar a exposição, inclua os custos para verificar a contribuição.</small></div><div class="item"><b>02 — Enviar fotos do cardápio</b><small>Use-as como insumo de avaliação visual e de desejo.</small></div>`:'<p class="sub">As recomendações surgem após a entrada de dados.</p>'}</div></section><section class="card" id="produtos"><h2>Produtos e engenharia de cardápio</h2><div class="scroll"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Vendas</th><th>Faturamento</th><th>Preço</th><th>Custo</th><th>Margem</th><th>Classificação</th></tr></thead><tbody>${rows||'<tr><td colspan="8">N/D — dado não disponível.</td></tr>'}</tbody></table></div><p class="sub" id="engenharia">Classificação é uma leitura inicial: popularidade e margem só são comparadas quando há custo informado.</p></section><section class="two"><div class="card" id="categorias"><h2>Categorias</h2>${categories.map(x=>`<div class="item"><b>${esc(x)}</b><small>${m.p.filter(p=>p.category===x).length} produto(s) · comparação de margem conforme custos disponíveis.</small></div>`).join('')||'<p class="sub">N/D — categorias não informadas.</p>'}</div><div class="card" id="margens"><h2>Preços & margens</h2><p class="sub">${m.avgMargin==null?'N/D — inclua custos para calcular margem de contribuição e alertas de food cost.':`Margem estimada: ${(m.avgMargin*100).toFixed(0)}%. Revise hipóteses de preço antes de concluir subprecificação.`}</p></div></section>${productForm(c)}<section class="two"><div class="card"><h2>Fotos do cardápio</h2><p class="sub">Envie fotos de produtos, cardápio impresso ou digital. Elas ficam no restaurante e aparecem como evidência no diagnóstico.</p><form method="post" enctype="multipart/form-data" action="/clientes/${c.id}/cardapio/fotos"><div class="field"><input required type="file" name="image" accept="image/*"></div><div class="field"><label>Produto relacionado (opcional)</label><input name="product"></div><button class="btn">Enviar foto</button></form>${(c.menuImages||[]).map(x=>`<figure><img src="${x.data}" alt="Foto enviada"><figcaption>${esc(x.product||x.name)}</figcaption></figure>`).join('')||'<p class="sub">Nenhuma foto enviada.</p>'}</div><div class="card" id="oportunidades"><h2>Oportunidades e cruzamentos</h2><div class="item" id="combos"><b>Combos & upsell</b><small>N/D — requer itens agrupados por pedido.</small></div><div class="item" id="conversao"><b>Conversão</b><small>N/D — requer visualizações, carrinho, checkout e pedidos.</small></div><div class="item"><b>Exposição × venda</b><small>N/D — envie prints do Instagram e associe produtos para cruzar a exposição.</small></div></div></section><section class="card" id="historico"><h2>Histórico</h2><p class="sub">Comparações mensais aparecem quando houver dois ou mais períodos importados para este cliente.</p></section>`);}

function instagramPage(c){return page(`Instagram · ${c.name}`,'instagram',`${tabs(c,'instagram')}<section class="two"><div class="card"><h2>Prints e evidências do Instagram</h2><p class="sub">Envie perfil, feed, Reels ou Insights. A imagem será guardada junto ao restaurante para o diagnóstico da Tríade.</p><form method="post" enctype="multipart/form-data" action="/clientes/${c.id}/instagram"><div class="field"><label>Screenshot</label><input required type="file" name="image" accept="image/*"></div><div class="field"><label>Contexto / período</label><textarea name="context" placeholder="Ex.: Insights de agosto, Reel do produto X, print do perfil..."></textarea></div><button class="btn">Enviar print</button></form><div class="notice">Leitura visual automática, OCR e reconhecimento de métricas exigem uma integração de IA configurada. Neste MVP, nenhum número é inventado a partir da imagem.</div></div><div class="card"><h2>Diagnóstico do Instagram</h2><div class="item"><b>Posicionamento e vitrine</b><small>${c.instagramImages?.length?'Há evidências enviadas para revisão.':'N/D — envie um print do perfil ou feed.'}</small></div><div class="item"><b>Conteúdo × produtos</b><small>N/D — vincule os prints aos produtos e inclua métricas para permitir cruzamento.</small></div><div class="item"><b>Conversão</b><small>N/D — requer alcance, visitas, cliques e pedidos.</small></div></div></section><section class="card"><h2>Imagens enviadas</h2>${(c.instagramImages||[]).map(x=>`<figure><img src="${x.data}" alt="Print do Instagram"><figcaption>${esc(x.context||x.name)}</figcaption></figure>`).join('')||'<p class="sub">Nenhum print enviado.</p>'}</section>`);}
function diagnosis(c){const m=metrics(c);const facts=[];const opportunities=[];if(m.p.length){facts.push(`${m.p.length} produto(s) registrado(s), ${m.orders} itens vendidos e ${money(m.revenue)} em faturamento agregado.`);const top=m.ranked[0];if(top)opportunities.push({title:'Validar e explorar o produto campeão',evidence:`${top.name} lidera a receita disponível com ${money(top.revenue)}.`,action:'Confirmar margem, qualidade visual e presença em conteúdo antes de aumentar a exposição.',pillar:'Cardápio',confidence:'Média'});if(m.p.some(x=>x.cost==null))opportunities.push({title:'Completar custos para avaliar margem',evidence:'Há produtos sem custo informado.',action:'Importar ficha de custo ou preencher custos unitários.',pillar:'Cardápio',confidence:'Alta'});if(m.ticket<50&&m.orders)opportunities.push({title:'Testar aumento de ticket',evidence:`Ticket médio por item calculado: ${money(m.ticket)}.`,action:'Testar adicional ou combo e acompanhar adesão e margem.',pillar:'Cardápio',confidence:'Baixa'});}else facts.push('Ainda não existem vendas ou produtos suficientes para uma avaliação comercial.');if(!(c.menuImages||[]).length)opportunities.push({title:'Adicionar fotos do cardápio',evidence:'Não há evidência visual dos produtos.',action:'Enviar fotos dos produtos e associá-las aos itens estratégicos.',pillar:'Conteúdo / Cardápio',confidence:'Alta'});if(!(c.instagramImages||[]).length)opportunities.push({title:'Adicionar prints do Instagram',evidence:'Não há dados de exposição e conteúdo.',action:'Enviar prints de perfil, feed, Reels ou Insights.',pillar:'Conteúdo',confidence:'Alta'});if(!c.onboarding?.notes)opportunities.push({title:'Registrar o onboarding',evidence:'Não há briefing textual salvo.',action:'Adicionar transcrição, resumo ou notas da reunião.',pillar:'Negócio',confidence:'Alta'});const menuScore=Math.min(10,2+(m.p.length?2:0)+(m.p.some(x=>x.cost!=null)?2:0)+(c.menuImages?.length?1:0));const contentScore=Math.min(10,2+(c.instagramImages?.length?2:0)+(c.onboarding?.notes?1:0));return {m,facts,opportunities,menuScore,contentScore,trafficScore:2};}
function diagnosticPage(c){const d=diagnosis(c), menuPhotos=c.menuImages?.length||0, instaPrints=c.instagramImages?.length||0;return page(`Diagnóstico 360° · ${c.name}`,'diag',`${tabs(c,'diag')}<div class="notice">Ferramenta interna de decisão: os escores abaixo são uma leitura inicial baseada apenas nas evidências disponíveis; não representam verdade absoluta.</div><section class="grid"><div class="card"><div class="label">CONTEÚDO</div><div class="big">${d.contentScore.toFixed(1)}<small>/10</small></div></div><div class="card"><div class="label">CARDÁPIO</div><div class="big">${d.menuScore.toFixed(1)}<small>/10</small></div></div><div class="card"><div class="label">TRÁFEGO</div><div class="big">${d.trafficScore.toFixed(1)}<small>/10</small></div></div><div class="card hero"><div class="label">ÍNDICE DE DECOLAGEM</div><div class="big">${(d.contentScore+d.menuScore+d.trafficScore).toFixed(1)}<small>/30</small></div></div></section><section class="two"><div class="card"><h2>O que aconteceu?</h2>${d.facts.map(x=>`<div class="item"><small>${esc(x)}</small></div>`).join('')}<div class="item"><small>Evidências visuais recebidas: ${menuPhotos} foto(s) de cardápio e ${instaPrints} print(s) de Instagram.</small></div></div><div class="card"><h2>Limitações atuais</h2><p class="sub">Não foram recebidos dados de tráfego, conversão por etapa, pedidos por cliente nem métricas completas de Instagram. Por isso, o sistema não atribui causa e efeito nem estima resultados.</p></div></section><section class="card"><h2>Principais oportunidades</h2>${d.opportunities.slice(0,5).map((o,i)=>`<div class="op"><span>P${i+1}</span><div><b>${esc(o.title)}</b><p><strong>Evidência:</strong> ${esc(o.evidence)}</p><p><strong>Ação:</strong> ${esc(o.action)}</p><small>${esc(o.pillar)} · Confiança ${esc(o.confidence)}</small></div></div>`).join('')}</section><section class="two"><div class="card"><h2>Fato disponível</h2><p class="sub">Dados importados e materiais enviados pelo time.</p></div><div class="card"><h2>Hipótese / recomendação</h2><p class="sub">Sempre separada dos fatos e apresentada como teste a validar.</p></div></section>`);}
function planPage(c){const actions=c.plan||[];return page(`Plano de Decolagem · ${c.name}`,'plan',`${tabs(c,'plan')}<section class="two"><div class="card"><h2>Plano inicial de 30 dias</h2><p class="sub">Edite o plano conforme a realidade da operação. As ações nascem das evidências disponíveis no diagnóstico.</p>${actions.map((a,i)=>`<form class="item" method="post" action="/clientes/${c.id}/plano/${i}"><label><input onchange="this.form.submit()" type="checkbox" ${a.done?'checked':''}> <b>${esc(a.title)}</b></label><small>${esc(a.pillar)} · ${esc(a.owner||'Responsável a definir')} · ${esc(a.kpi||'KPI a definir')}</small></form>`).join('')||'<p class="sub">Nenhuma ação cadastrada.</p>'}</div><div class="card"><h2>Gerar a partir do diagnóstico</h2><p class="sub">Cria ações editáveis a partir das oportunidades disponíveis, sem substituir o julgamento da equipe.</p><form method="post" action="/clientes/${c.id}/plano/gerar"><button class="btn">Gerar plano inicial</button></form><hr><h2>Nova ação</h2><form method="post" action="/clientes/${c.id}/plano"><div class="field"><label>Ação</label><input name="title" required></div><div class="field"><label>Pilar</label><select name="pillar"><option>Conteúdo</option><option>Cardápio</option><option>Tráfego</option><option>CRM</option></select></div><div class="field"><label>Responsável sugerido</label><input name="owner" placeholder="Ex.: Conteúdo"></div><div class="field"><label>Indicador</label><input name="kpi" placeholder="Ex.: ticket médio"></div><button class="btn">Adicionar ao plano</button></form></div></section>`);}

const pendingCampaigns=new Map();
function campaignStatus(status){const tone=status==='Ativa'?'ok':status==='Erro'?'bad':status==='Pausada'?'warn':'tag';return `<span class="${tone==='tag'?'tag':`status ${tone}`}">${esc(status)}</span>`;}
function campaignMetrics(){const real=db.campaigns||[];return {active:real.filter(x=>x.status==='Ativa').length,paused:real.filter(x=>x.status==='Pausada').length,alerts:real.filter(x=>x.status==='Erro').length,budget:real.reduce((a,x)=>a+num(x.budgetDaily),0)};}
function campaignsPage(query){const qClient=query?.get('client')||'',qStatus=query?.get('status')||'Todos';const real=(db.campaigns||[]).filter(x=>(!qClient||x.clientId===qClient)&& (qStatus==='Todos'||x.status===qStatus));const cm=campaignMetrics();const rows=real.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.objective||'Objetivo não definido')}</small></td><td>${esc(x.clientName||'Cliente não informado')}</td><td>${esc(x.platform||'Meta')}</td><td>${money(x.budgetDaily||0)}/dia</td><td>${campaignStatus(x.status)}</td><td>${esc(x.createdAt?.slice(0,10)||'—')}</td><td><a class="table-link" href="/campanhas/${x.id}">Revisar</a></td></tr>`).join('');const demo=demoCampaigns.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.clientName)}</td><td>Meta</td><td>${money(x.budgetDaily)}/dia</td><td>${campaignStatus(x.status)}</td><td>${esc(x.startedAt)}</td><td><span class="tag">DEMO</span></td></tr>`).join('');return page('Campanhas','campaigns',`<div class="notice">${adliftr.connected?'AdLiftr configurado no servidor.':'AdLiftr não conectado — modo demonstração e rascunhos locais ativos.'}</div><div class="dash-head"><div><p class="sub">Crie, revise e mantenha campanhas pausadas até a confirmação da equipe.</p></div><a class="btn" href="/campanhas/nova">+ Nova campanha</a></div><section class="grid"><div class="card"><div class="label">CAMPANHAS ATIVAS</div><div class="big">${cm.active}</div></div><div class="card"><div class="label">PAUSADAS</div><div class="big">${cm.paused}</div></div><div class="card"><div class="label">COM ALERTA</div><div class="big">${cm.alerts}</div></div><div class="card"><div class="label">ORÇAMENTO DIÁRIO</div><div class="big">${cm.budget?money(cm.budget):'—'}</div></div></section><section class="card"><h2>Operação da equipe</h2><form class="dash-filter" method="get" action="/campanhas"><label>CLIENTE</label><select name="client"><option value="">Todos</option>${db.clients.map(c=>`<option value="${c.id}" ${qClient===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label>STATUS</label><select name="status">${['Todos','Rascunho','Pausada','Ativa','Encerrada','Erro'].map(x=>`<option ${qStatus===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn">Filtrar</button></form><div class="scroll"><table><thead><tr><th>Campanha</th><th>Cliente</th><th>Plataforma</th><th>Orçamento</th><th>Status</th><th>Data</th><th>Ação</th></tr></thead><tbody>${rows||'<tr><td colspan="7">Nenhuma campanha real criada.</td></tr>'}</tbody></table></div></section><section class="card"><h2>Modo demonstração</h2><p class="sub">Dados fictícios separados da operação real. Não são enviados para Meta.</p><div class="scroll"><table><thead><tr><th>Campanha</th><th>Cliente</th><th>Plataforma</th><th>Orçamento</th><th>Status</th><th>Data</th><th>Origem</th></tr></thead><tbody>${demo}</tbody></table></div></section>`);}
function newCampaignPage(){return page('Nova campanha','campaigns',`<div class="notice">Fluxo seguro: preencher → revisar → criar como <b>PAUSADA</b>. Nenhuma verba será ativada automaticamente.</div><form method="post" action="/campanhas/revisar" enctype="multipart/form-data"><section class="card"><h2>1. Cliente e conta de anúncios</h2><div class="field"><label>Cliente</label><select required name="clientId">${db.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Conta de anúncios</label><select required name="accountId"><option value="">Selecione uma conta cadastrada</option>${db.clients.flatMap(c=>(c.adAccounts||[]).map(a=>`<option value="${a.id}">${esc(c.name)} · ${esc(a.name)} · ${esc(a.platform)}</option>`)).join('')}</select><small>Cadastre a conta no cliente antes de criar a campanha.</small></div></section><section class="card"><h2>2. Informações da campanha</h2><div class="field"><label>Nome da campanha</label><input required name="name" placeholder="Cliente | Objetivo | Mês"></div><div class="field"><label>Objetivo</label><select name="objective"><option>Vendas</option><option>Leads</option><option>Tráfego</option><option>Reconhecimento</option><option>Mensagens</option></select></div><div class="two"><div class="field"><label>Orçamento diário (R$)</label><input name="budgetDaily" type="number" min="0" step="0.01"></div><div class="field"><label>Orçamento total (R$)</label><input name="budgetTotal" type="number" min="0" step="0.01"></div></div><div class="two"><div class="field"><label>Data inicial</label><input name="startDate" type="date"></div><div class="field"><label>Data final</label><input name="endDate" type="date"></div></div></section><section class="card"><h2>3. Configuração do conjunto</h2><div class="two"><div class="field"><label>Público</label><input name="audience" placeholder="Ex.: clientes locais"></div><div class="field"><label>Localização</label><input name="location" placeholder="Cidade / raio"></div></div><div class="two"><div class="field"><label>Idade</label><input name="age" placeholder="Ex.: 25–55"></div><div class="field"><label>Gênero</label><select name="gender"><option>Todos</option><option>Mulheres</option><option>Homens</option></select></div></div><div class="two"><div class="field"><label>Posicionamentos</label><input name="placements" placeholder="Advantage+ / Feed / Reels"></div><div class="field"><label>Evento de conversão</label><input name="conversionEvent" placeholder="Ex.: Purchase / Lead"></div></div></section><section class="card"><h2>4. Criativo principal</h2><div class="field"><label>Imagem, vídeo ou URL</label><input name="creative" type="file" accept="image/*,video/*"><input name="creativeUrl" type="url" placeholder="ou cole a URL do criativo"></div><div class="field"><label>Texto principal</label><textarea name="primaryText"></textarea></div><div class="two"><div class="field"><label>Headline</label><input name="headline"></div><div class="field"><label>Descrição</label><input name="description"></div></div><div class="two"><div class="field"><label>CTA</label><select name="cta"><option>Saiba mais</option><option>Comprar agora</option><option>Enviar mensagem</option><option>Cadastre-se</option></select></div><div class="field"><label>URL de destino</label><input name="destinationUrl" type="url"></div></div><div class="field"><label>UTM</label><input name="utm" placeholder="utm_source=meta&utm_medium=paid"></div></section><section class="card"><h2>5. Revisão</h2><p class="sub">A próxima etapa mostrará exatamente o que será criado. O status inicial será sempre pausado.</p><button class="btn">Continuar para revisão →</button></section></form>`);}
function campaignReview(token){const p=pendingCampaigns.get(token);if(!p)return page('Revisão expirada','campaigns','<section class="card"><p>Esta revisão expirou. Comece novamente.</p><a class="btn" href="/campanhas/nova">Nova campanha</a></section>');const c=client(p.clientId),account=(c?.adAccounts||[]).find(a=>a.id===p.accountId);return page('Revisar campanha','campaigns',`<div class="notice">Nada será publicado nesta etapa. A confirmação criará a campanha local com status <b>PAUSADA</b>.</div><section class="card"><h2>O que será criado</h2><div class="item"><b>Cliente</b><small>${esc(c?.name||'Não informado')}</small></div><div class="item"><b>Conta</b><small>${esc(account?.name||'Não encontrada')} · ${esc(account?.platform||'Meta')} · ${esc(account?.connectionStatus||'Não conectado')}</small></div><div class="item"><b>Campanha</b><small>${esc(p.name)} · ${esc(p.objective)}</small></div><div class="item"><b>Orçamento</b><small>${p.budgetDaily?money(p.budgetDaily)+'/dia':'Não informado'}${p.budgetTotal?' · '+money(p.budgetTotal)+' total':''}</small></div><div class="item"><b>Conjunto</b><small>${esc(p.audience||'Público não informado')} · ${esc(p.location||'Localização não informada')} · ${esc(p.placements||'Posicionamentos não informados')}</small></div><div class="item"><b>Criativos</b><small>${p.creativeName||p.creativeUrl?'1 criativo anexado':'Nenhum criativo anexado'}</small></div><div class="notice ok">Status inicial: PAUSADA</div><form method="post" action="/campanhas/criar"><input type="hidden" name="token" value="${token}"><button class="btn">Criar campanha pausada</button> <a class="btn" style="background:#3a294d" href="/campanhas/nova">Voltar e editar</a></form></section>`);}
function campaignDetail(camp){const c=client(camp.clientId);return page(camp.name,'campaigns',`<div class="notice">Esta campanha está armazenada localmente. AdLiftr: ${adliftr.connected?'configurado':'não conectado'}.</div><section class="two"><div class="card"><h2>Resumo</h2><div class="item"><b>Cliente</b><small>${esc(c?.name||camp.clientName)}</small></div><div class="item"><b>Objetivo</b><small>${esc(camp.objective)}</small></div><div class="item"><b>Orçamento</b><small>${camp.budgetDaily?money(camp.budgetDaily)+'/dia':'N/D'}</small></div><div class="item"><b>Status</b><small>${campaignStatus(camp.status)}</small></div></div><div class="card"><h2>Próxima etapa</h2><p class="sub">Revise os dados antes de qualquer conexão externa. Nenhuma publicação automática está disponível.</p><button class="btn" disabled>Publicar (indisponível)</button></div></section>`);}
function creativesPage(){const rows=(db.creatives||[]).map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.clientName||'—')}</td><td>${esc(x.type||'Arquivo')}</td><td>${esc(x.campaignName||'Não associado')}</td><td>${esc(x.createdAt?.slice(0,10)||'—')}</td></tr>`).join('');return page('Criativos','creatives',`<div class="notice">Área de biblioteca criativa. Arquivos ficam no sistema até serem revisados pela equipe.</div><section class="card"><h2>Biblioteca de criativos</h2><div class="scroll"><table><thead><tr><th>Nome</th><th>Cliente</th><th>Tipo</th><th>Campanha</th><th>Data</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Nenhum criativo salvo. Adicione-o dentro do criador de campanha.</td></tr>'}</tbody></table></div></section>`);}
function monitoringPage(){const real=db.campaigns||[];return page('Monitoramento','monitor',`<div class="notice">AdLiftr não conectado — não há métricas reais sendo consultadas. Esta tela não inventa performance.</div><section class="grid"><div class="card"><div class="label">CAMPANHAS MONITORADAS</div><div class="big">${real.length||'—'}</div></div><div class="card"><div class="label">IMPRESSÕES</div><div class="big">—</div><small class="sub">N/D sem sincronização</small></div><div class="card"><div class="label">LEADS</div><div class="big">—</div><small class="sub">N/D sem sincronização</small></div><div class="card"><div class="label">ROAS</div><div class="big">—</div><small class="sub">N/D sem sincronização</small></div></section><section class="card"><h2>Última sincronização</h2><p class="sub">Nenhuma sincronização foi executada. Configure o AdLiftr no ambiente do servidor quando houver autorização para integrar.</p></section>`);}
function automationsPage(){return page('Automações','automations',`<div class="notice">As automações ficam preparadas, mas não executam alterações em campanhas nesta versão.</div><section class="two"><div class="card"><h2>Regras futuras</h2><div class="item"><b>Alerta de queda de performance</b><small>Somente recomendação; nenhuma pausa automática.</small></div><div class="item"><b>Identificação de anúncio vencedor</b><small>Requer métricas reais sincronizadas.</small></div><div class="item"><b>Controle de orçamento</b><small>Exigirá revisão e confirmação humana.</small></div></div><div class="card"><h2>Logs</h2><p class="sub">Nenhum log de automação. O sistema não executa campanhas reais automaticamente.</p></div></section>`);}
function settingsPage(){return page('Configurações','settings',`<section class="two"><div class="card"><h2>Conexão com AdLiftr</h2><div class="notice">${adliftr.connected?'AdLiftr configurado no ambiente do servidor.':'AdLiftr não conectado'}</div><p class="sub">A chave nunca é exibida no navegador. Configure <b>ADLIFTR_API_KEY</b> e <b>ADLIFTR_API_URL</b> somente no servidor.</p></div><div class="card"><h2>Modo de operação</h2><div class="item"><b>Modo demonstração</b><small>Campanhas fictícias aparecem separadas das campanhas reais locais.</small></div><div class="item"><b>Regra de segurança</b><small>Criar → Pausada → Revisar → Confirmar → Publicar.</small></div></div></section>`);}

function hasValue(v){return v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v));}
function contentStats(c){
  const posts=c.contentPosts||[], views=posts.map(p=>num(p.views||p.reach)), desire=posts.map(p=>num(p.shares)+num(p.saves)), conversion=posts.map(p=>num(p.clicks)+num(p.orders)), sales=posts.map(p=>num(p.revenue));
  const max=(arr)=>Math.max(0,...arr), champion=(arr)=>{const top=max(arr);return top>0?posts.filter((p,i)=>arr[i]>0&&arr[i]>=top*.7):[]};
  const attention=champion(views), desireChamp=champion(desire), conversionChamp=champion(conversion), salesChamp=champion(sales); const champions=[...new Set([...attention,...desireChamp,...conversionChamp,...salesChamp])];
  const productCount={};const formatCount={};for(const p of posts){if(p.product)productCount[p.product]=(productCount[p.product]||0)+1;if(p.format)formatCount[p.format]=(formatCount[p.format]||0)+1;}
  const topProduct=Object.entries(productCount).sort((a,b)=>b[1]-a[1])[0]?.[0]||'N/D';const topFormat=Object.entries(formatCount).sort((a,b)=>b[1]-a[1])[0]?.[0]||'N/D';
  const patterns=posts.length?`Os dados disponíveis apontam ${topFormat} como formato mais recorrente${topProduct!=='N/D'?` e ${topProduct} como produto mais explorado`:''}. Confirme com mais posts antes de transformar isso em regra.`:'N/D — analise pelo menos dois posts para identificar padrões.';
  const opportunity=!posts.length?'Envie prints e métricas de posts para descobrir o que gera atenção, desejo e conversão.':posts.some(p=>!hasValue(p.clicks)&&!hasValue(p.orders))?'Há desempenho de atenção, mas faltam cliques ou pedidos atribuídos para avaliar conversão.':'Cruzar posts campeões com margem e vendas do cardápio para encontrar oportunidades de escala.';
  return {posts,attention,desireChamp,conversionChamp,salesChamp,champions,topProduct,topFormat,patterns,opportunity};
}
function contentPage(c){
  const s=contentStats(c), products=(c.products||[]).map(p=>`<option>${esc(p.name)}</option>`).join(''), ideas=c.contentLastIdeas||[], script=c.contentLastScript;
  const postRows=s.posts.map(p=>`<tr><td><b>${esc(p.title||'Post sem título')}</b><small>${esc(p.date||'Data N/D')} · ${esc(p.format||'Formato N/D')}</small></td><td>${esc(p.product||'N/D')}</td><td>${p.views||p.reach||'N/D'}</td><td>${p.shares||p.saves?'Desejo':'N/D'}</td><td>${p.clicks||p.orders?'Conversão':'N/D'}</td><td>${s.attention.includes(p)||s.desireChamp.includes(p)||s.conversionChamp.includes(p)||s.salesChamp.includes(p)?'<span class="tag">POST CAMPEÃO</span>':'N/D'}</td></tr>`).join('');
  return page(`Conteúdo · ${c.name}`,'content',`${tabs(c,'content')}<div class="notice">Análise estruturada a partir de prints e dados inseridos. Nenhuma métrica é inventada; a integração automática com Instagram permanece opcional.</div><section class="grid"><div class="card"><div class="label">CONTEÚDOS ANALISADOS</div><div class="big">${s.posts.length||'—'}</div></div><div class="card"><div class="label">POSTS CAMPEÕES</div><div class="big">${s.champions.length||'—'}</div><small class="sub">Atenção, desejo, conversão ou vendas</small></div><div class="card"><div class="label">PRODUTO MAIS EXPLORADO</div><div class="big" style="font-size:18px">${esc(s.topProduct)}</div></div><div class="card"><div class="label">FORMATO MAIS EFICIENTE</div><div class="big" style="font-size:18px">${esc(s.topFormat)}</div></div></section><section class="two"><div class="card"><h2>Melhor padrão identificado</h2><p class="sub">${esc(s.patterns)}</p></div><div class="card"><h2>Oportunidade atual</h2><p class="sub">${esc(s.opportunity)}</p></div></section><section class="two"><div class="card"><h2>Analisar post</h2><p class="sub">Cadastre prints e métricas manualmente. O post passa a alimentar padrões e campeões.</p><form method="post" action="/conteudo/post" enctype="multipart/form-data"><input type="hidden" name="clientId" value="${c.id}"><div class="field"><label>Título / nome</label><input required name="title"></div><div class="two"><div class="field"><label>Data</label><input name="date" type="date"></div><div class="field"><label>Formato</label><select name="format"><option>Reel</option><option>POV</option><option>ASMR</option><option>Bastidores</option><option>Montagem</option><option>Carrossel</option><option>Foto</option><option>Oferta</option></select></div></div><div class="two"><div class="field"><label>Produto</label><select name="product"><option value="">N/D</option>${products}</select></div><div class="field"><label>Função</label><select name="functionType"><option>Atração</option><option>Desejo</option><option>Prova</option><option>Conversão</option><option>Relacionamento</option><option>Retenção</option></select></div></div><div class="field"><label>Print, imagem ou vídeo</label><input name="asset" type="file" accept="image/*,video/*"></div><div class="field"><label>Legenda / hook / CTA</label><textarea name="copy" placeholder="Cole a legenda e descreva hook e CTA."></textarea></div><div class="field"><label>Métricas</label><div class="two"><input name="reach" type="number" placeholder="Alcance"><input name="views" type="number" placeholder="Visualizações"></div><div class="two"><input name="likes" type="number" placeholder="Curtidas"><input name="comments" type="number" placeholder="Comentários"></div><div class="two"><input name="shares" type="number" placeholder="Compartilhamentos"><input name="saves" type="number" placeholder="Salvamentos"></div><div class="two"><input name="profileVisits" type="number" placeholder="Visitas ao perfil"><input name="clicks" type="number" placeholder="Cliques"></div><div class="two"><input name="orders" type="number" placeholder="Pedidos atribuídos"><input name="revenue" type="number" step="0.01" placeholder="Faturamento atribuído"></div></div><div class="field"><label>Observações</label><textarea name="observations"></textarea></div><button class="btn">Salvar e analisar post</button></form></div><div class="card"><h2>Posts campeões</h2><div class="item"><b>Campeão de atenção</b><small>${s.attention.map(p=>esc(p.title)).join(', ')||'N/D'}</small></div><div class="item"><b>Campeão de desejo</b><small>${s.desireChamp.map(p=>esc(p.title)).join(', ')||'N/D'}</small></div><div class="item"><b>Campeão de conversão</b><small>${s.conversionChamp.map(p=>esc(p.title)).join(', ')||'N/D'}</small></div><div class="item"><b>Campeão de vendas</b><small>${s.salesChamp.map(p=>esc(p.title)).join(', ')||'N/D'}</small></div><p class="sub">Um post não é campeão apenas por curtidas: a classificação usa os sinais disponíveis e mostra N/D quando faltam dados.</p></div></section><section class="card"><h2>Conteúdos cadastrados</h2><div class="scroll"><table><thead><tr><th>Post</th><th>Produto</th><th>Atenção</th><th>Desejo</th><th>Conversão</th><th>Classificação</th></tr></thead><tbody>${postRows||'<tr><td colspan="6">Nenhum post analisado.</td></tr>'}</tbody></table></div></section><section class="two"><div class="card"><h2>Gerar ideias</h2><p class="sub">As ideias usam produtos do cardápio e os padrões registrados neste cliente.</p><form method="post" action="/conteudo/ideias"><input type="hidden" name="clientId" value="${c.id}"><div class="field"><label>Objetivo</label><select name="objective"><option>Atrair</option><option>Gerar desejo</option><option>Vender</option><option>Aumentar ticket</option><option>Divulgar produto</option><option>Gerar WhatsApp</option><option>Reativar clientes</option></select></div><div class="field"><label>Produto</label><select name="product"><option value="">Produto-herói / melhor disponível</option>${products}</select></div><div class="field"><label>Formato</label><select name="format"><option>Reel</option><option>POV</option><option>ASMR</option><option>Bastidores</option><option>Montagem</option><option>Storytelling</option><option>Unboxing</option><option>Oferta</option></select></div><div class="field"><label>Quantidade</label><select name="quantity"><option>5</option><option>10</option><option>20</option></select></div><button class="btn">Gerar ideias</button></form>${ideas.length?`<div class="notice ok"><b>Ideias geradas com base em ${esc(ideas[0].product)}:</b><ol>${ideas.map(i=>`<li>${esc(i.text)}</li>`).join('')}</ol></div>`:''}</div><div class="card"><h2>Criar roteiro</h2><p class="sub">O roteiro sempre separa hook, corpo, áudio, texto, objetivo e CTA.</p><form method="post" action="/conteudo/roteiro"><input type="hidden" name="clientId" value="${c.id}"><div class="field"><label>Produto</label><select name="product">${products||'<option>Produto N/D</option>'}</select></div><div class="two"><div class="field"><label>Objetivo</label><select name="objective"><option>Gerar desejo</option><option>Vender</option><option>Atrair</option><option>Aumentar ticket</option></select></div><div class="field"><label>Formato</label><select name="format"><option>Reel</option><option>POV</option><option>ASMR</option><option>Unboxing</option><option>Bastidores</option></select></div></div><div class="two"><div class="field"><label>Duração</label><input name="duration" placeholder="Ex.: 15s"></div><div class="field"><label>CTA</label><select name="cta"><option>Peça pelo cardápio digital</option><option>Chame no WhatsApp</option><option>Acesse o link da bio</option></select></div></div><button class="btn">Criar roteiro</button></form>${script?`<div class="notice ok"><b>Roteiro gerado para ${esc(script.product)}</b><p><strong>HOOK — 0–3s:</strong> ${esc(script.hook)}</p><p><strong>CORPO:</strong> ${esc(script.body)}</p><p><strong>Áudio:</strong> ${esc(script.audio)}</p><p><strong>Texto:</strong> ${esc(script.text)}</p><p><strong>Objetivo:</strong> ${esc(script.objective)}</p><p><strong>CTA:</strong> ${esc(script.cta)}</p></div>`:''}</div></section>`);
}
function generateIdeas(c,fields){const m=metrics(c), product=fields.product||m.hero?.name||'produto principal', quantity=Math.min(20,Math.max(1,Number(fields.quantity)||5)), format=fields.format||'Reel', objective=fields.objective||'Gerar desejo';const bases=[`Close-up de ${product} com textura e corte no primeiro segundo, em formato ${format}, para ${objective.toLocaleLowerCase()}.`,`Bastidor da montagem de ${product}: preparação → transformação → produto final, com CTA para o cardápio digital.`,`POV de alguém recebendo ${product}, mostrando embalagem, abertura e primeira mordida sem afirmar resultados não medidos.`,`Comparação visual de ${product} em duas versões, destacando diferencial real informado pelo restaurante.`,`Oferta contextual de ${product} com preço apenas se cadastrado; caso contrário, CTA para consultar o cardápio.`,`ASMR de chapa, crocância e montagem de ${product}, usando o som como hook de atenção.`,`Depoimento ou prova social sobre ${product}, desde que exista cliente autorizado e evidência disponível.`,`Série de três cenas para ${product}: desejo, prova e caminho de pedido próprio.`];return Array.from({length:quantity},(_,i)=>({text:bases[i%bases.length]}));}
function buildScript(fields){const product=fields.product||'produto principal',objective=fields.objective||'Gerar desejo',format=fields.format||'Reel',duration=fields.duration||'15s',cta=fields.cta||'Peça pelo cardápio digital';return {product,objective,format,duration,cta,hook:`Mostrar ${product} em close-up no primeiro segundo: corte, textura ou movimento que quebre o padrão.`,body:`Cena 1: produto entrando em quadro. Cena 2: preparo e transformação. Cena 3: detalhe sensorial e montagem. Cena 4: produto final e caminho claro para pedir.`,audio:`Som real de preparo e montagem (ASMR)${format==='Reel'?' com trilha baixa':''}.`,text:`${product} do jeito que dá vontade.`,};}

function normalizedHeader(value){return String(value||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
function autoMapping(headers){return headers.map(h=>{const n=normalizedHeader(h);if(/produto|item|descricao/.test(n))return'PRODUCT_NAME';if(/categoria|grupo/.test(n))return'CATEGORY';if(/quantidade|qtd|unidades|volume/.test(n))return'QUANTITY';if(/custo|cmv/.test(n))return'COST';if(/preco medio|preco unitario|preco/.test(n))return'PRICE';if(/faturamento|receita|valor total|total venda/.test(n))return'REVENUE';return'IGNORE';});}
function parseNumber(value){let text=String(value||'').replace(/R\$|\s/g,'').replace(/[^0-9,.-]/g,'');if(text.includes(',')&&text.includes('.')){text=text.lastIndexOf(',')>text.lastIndexOf('.')?text.replace(/\./g,'').replace(',','.'):text.replace(/,/g,'');}else if(text.includes(','))text=text.replace(',','.');return Number(text)||0;}
function fromMap(row,headers,map,target){const at=map.findIndex(x=>x===target);return at<0?'':row[headers[at]];}
function applyProducts(c,rows,headers,map){
  let added=0;
  for(const r of rows){
    const name=fromMap(r,headers,map,'PRODUCT_NAME');
    if(!name)continue;
    const category=fromMap(r,headers,map,'CATEGORY');
    const quantity=parseNumber(fromMap(r,headers,map,'QUANTITY'));
    const price=parseNumber(fromMap(r,headers,map,'PRICE'));
    const revenue=parseNumber(fromMap(r,headers,map,'REVENUE')) || quantity*price;
    const rawCost=fromMap(r,headers,map,'COST'); const cost=rawCost===''?null:parseNumber(rawCost);
    const existing=c.products.find(p=>p.name.toLowerCase()===name.toLowerCase());
    if(existing){existing.quantity=num(existing.quantity)+quantity;existing.revenue=num(existing.revenue)+revenue;existing.price=price||existing.price;existing.cost=cost==null?existing.cost:cost;existing.category=category||existing.category;}
    else c.products.push({name,category,quantity,revenue,price,cost});
    added++;
  }
  return added;
}
function imageRecord(file,extra={}){if(!file?.data?.length)return null;if(file.data.length>4*1024*1024)throw Error('A imagem ultrapassa o limite de 4 MB deste MVP.');return {id:id(),name:file.name,type:file.type,data:`data:${file.type};base64,${file.data.toString('base64')}`,...extra};}
function mediaRecord(file){if(!file?.data?.length)return null;if(file.data.length>20*1024*1024)throw Error('O criativo ultrapassa o limite de 20 MB deste MVP.');return {id:id(),name:file.name,type:file.type,size:file.data.length,data:`data:${file.type};base64,${file.data.toString('base64')}`};}
function html(res,body,status=200){res.writeHead(status,{'Content-Type':'text/html; charset=utf-8'});res.end(body);}
function notFound(res){html(res,page('Página não encontrada','',`<section class="card"><p>Não foi possível encontrar esta página.</p><a class="btn" href="/">Voltar ao início</a></section>`),404);}

http.createServer(async(req,res)=>{
  try{
    const url=new URL(req.url,`http://${req.headers.host||'localhost'}`); const parts=url.pathname.split('/').filter(Boolean); const active=getActive(url.searchParams);
    if(url.pathname==='/health'){res.writeHead(200,{'Content-Type':'text/plain; charset=utf-8'});return res.end('ok');}
    if(url.pathname==='/sair'){res.writeHead(303,{'Location':'/login','Set-Cookie':'decola_session=; Max-Age=0; HttpOnly; SameSite=Lax; Path=/'});return res.end();}
    if(authEnabled()&&!['/login'].includes(url.pathname)){const session=cookieValue(req,'decola_session');if(!session||!authSessions.has(session))return redirect(res,'/login');}
    if(req.method==='GET'){
      if(url.pathname==='/login')return html(res,loginPage());
      if(url.pathname==='/')return html(res,home(url.searchParams));
      if(url.pathname==='/clientes')return html(res,clients());
      if(url.pathname==='/clientes/novo')return html(res,newClient());
      if(parts[0]==='clientes'&&parts.length===2){const c=client(parts[1]);return c?html(res,clientPage(c)):notFound(res);}
      if(parts[0]==='clientes'&&parts[2]==='onboarding'){const c=client(parts[1]);return c?html(res,onboardingPage(c)):notFound(res);}
      if(url.pathname==='/importar')return active?html(res,importPage(active)):html(res,noClientPage('Importar dados'));
      if(url.pathname==='/importar/confirmar')return html(res,importConfirm(url.searchParams.get('token')));
      if(url.pathname==='/cardapio')return active?html(res,menuPage(active)):html(res,noClientPage('Cardápio'));
      if(url.pathname==='/instagram')return active?html(res,instagramPage(active)):html(res,noClientPage('Instagram'));
      if(url.pathname==='/conteudo')return active?html(res,contentPage(active)):html(res,noClientPage('Conteúdo'));
      if(url.pathname==='/diagnostico')return active?html(res,diagnosticPage(active)):html(res,noClientPage('Diagnóstico 360°'));
      if(url.pathname==='/plano')return active?html(res,planPage(active)):html(res,noClientPage('Plano de Decolagem'));
      if(url.pathname==='/campanhas')return html(res,campaignsPage(url.searchParams));
      if(url.pathname==='/campanhas/nova')return html(res,newCampaignPage());
      if(url.pathname==='/campanhas/revisar')return html(res,campaignReview(url.searchParams.get('token')));
      if(parts[0]==='campanhas'&&parts.length===2){const camp=(db.campaigns||[]).find(x=>x.id===parts[1]);return camp?html(res,campaignDetail(camp)):notFound(res);}
      if(url.pathname==='/criativos')return html(res,creativesPage());
      if(url.pathname==='/monitoramento')return html(res,monitoringPage());
      if(url.pathname==='/automacoes')return html(res,automationsPage());
      if(url.pathname==='/configuracoes')return html(res,settingsPage());
      return notFound(res);
    }
    const body=await read(req); const multi=(req.headers['content-type']||'').includes('multipart/form-data'); const {fields,files}=multi?multipart(req,body):{fields:form(body),files:[]};
    if(req.method==='POST'&&url.pathname==='/login'){if(!authEnabled()||fields.code===process.env.DECOLA_AUTH_CODE){const session=id();authSessions.set(session,{createdAt:Date.now()});res.writeHead(303,{'Location':'/','Set-Cookie':`decola_session=${session}; HttpOnly; SameSite=Lax; Path=/`});return res.end();}return html(res,loginPage('Código inválido.'),401);}
    if(req.method==='POST'&&url.pathname==='/clientes'){
      const c={id:id(),name:fields.name,brandName:fields.brandName||fields.name,segment:fields.segment,city:fields.city,state:fields.state,instagram:fields.instagram,site:fields.site,observations:fields.observations,owner:'A definir',status:'Ativo',startedAt:fields.startedAt,goal:fields.goal,onboarding:{notes:''},imports:[],products:[],menuImages:[],instagramImages:[],contentPosts:[],adAccounts:[],plan:[]};db.clients.push(c);save();return redirect(res,`/clientes/${c.id}`);
    }
    if(req.method==='POST'&&parts[0]==='clientes'){
      const c=client(parts[1]); if(!c)return notFound(res);
      if(parts[2]==='excluir'){db.clients=db.clients.filter(item=>item.id!==c.id);db.campaigns=db.campaigns.filter(item=>item.clientId!==c.id);db.creatives=db.creatives.filter(item=>item.clientId!==c.id);save();return redirect(res,'/clientes');}
      if(parts[2]==='contas'){c.adAccounts.push({id:id(),platform:fields.platform||'Meta',accountId:fields.accountId, name:fields.accountName, connectionStatus:'Não conectado'});save();return redirect(res,`/clientes/${c.id}`);}
      if(parts[2]==='onboarding'){const doc=files.find(x=>x.field==='document');let notes=fields.notes||'';if(doc&&/\.docx$/i.test(doc.name)&&!notes){try{notes=docxText(doc.data);}catch(_){}}if(doc&&/\.txt$/i.test(doc.name)&&!notes)notes=doc.data.toString('utf8');c.onboarding={notes,document:doc?{name:doc.name,type:doc.type,size:doc.data.length}:c.onboarding.document};save();return redirect(res,`/clientes/${c.id}/onboarding`);}
      if(parts[2]==='produtos'){const quantity=num(fields.quantity),price=num(fields.price);c.products.push({name:fields.name,category:fields.category,quantity,revenue:quantity*price,price,cost:fields.cost===''?null:num(fields.cost)});save();return redirect(res,`/cardapio?client=${c.id}`);}
      if(parts[2]==='cardapio'&&parts[3]==='fotos'){const img=imageRecord(files.find(x=>x.field==='image'),{product:fields.product});if(img)c.menuImages.push(img);save();return redirect(res,`/cardapio?client=${c.id}`);}
      if(parts[2]==='instagram'){const img=imageRecord(files.find(x=>x.field==='image'),{context:fields.context});if(img)c.instagramImages.push(img);save();return redirect(res,`/instagram?client=${c.id}`);}
      if(parts[2]==='plano'&&parts[3]==='gerar'){const generated=diagnosis(c).opportunities.slice(0,5).map(o=>({title:o.action,pillar:o.pillar.includes('Cardápio')?'Cardápio':o.pillar.includes('Conteúdo')?'Conteúdo':o.pillar.includes('CRM')?'CRM':'Tráfego',owner:'Equipe Decola',kpi:'Validar hipótese',done:false}));for(const item of generated)if(!c.plan.some(x=>x.title===item.title))c.plan.push(item);save();return redirect(res,`/plano?client=${c.id}`);}
      if(parts[2]==='plano'&&parts.length===3){c.plan.push({title:fields.title,pillar:fields.pillar,owner:fields.owner,kpi:fields.kpi,done:false});save();return redirect(res,`/plano?client=${c.id}`);}
      if(parts[2]==='plano'&&parts[3]!=null){const action=c.plan[Number(parts[3])];if(action)action.done=!action.done;save();return redirect(res,`/plano?client=${c.id}`);}
    }
    if(req.method==='POST'&&url.pathname==='/campanhas/revisar'){
      const c=client(fields.clientId),account=(c?.adAccounts||[]).find(a=>a.id===fields.accountId);if(!c||!account)return html(res,page('Conta necessária','campaigns','<section class="card"><h2>Cadastre uma conta de anúncios antes de continuar.</h2><p class="sub">Nenhuma campanha foi criada.</p><a class="btn" href="/clientes">Voltar para clientes</a></section>'),400);
      const creative=mediaRecord(files.find(x=>x.field==='creative'));const token=id();pendingCampaigns.set(token,{...fields,clientId:c.id,accountId:account.id,creativeData:creative,creativeName:creative?.name||'',createdAt:new Date().toISOString()});return redirect(res,`/campanhas/revisar?token=${token}`);
    }
    if(req.method==='POST'&&url.pathname==='/conteudo/post'){
      const c=client(fields.clientId);if(!c)return notFound(res);const asset=mediaRecord(files.find(x=>x.field==='asset'));c.contentPosts.push({id:id(),title:fields.title,date:fields.date,format:fields.format,product:fields.product,functionType:fields.functionType,copy:fields.copy,reach:fields.reach,views:fields.views,likes:fields.likes,comments:fields.comments,shares:fields.shares,saves:fields.saves,profileVisits:fields.profileVisits,clicks:fields.clicks,orders:fields.orders,revenue:fields.revenue,investment:fields.investment,observations:fields.observations,asset,createdAt:new Date().toISOString()});save();return redirect(res,`/conteudo?client=${c.id}`);
    }
    if(req.method==='POST'&&url.pathname==='/conteudo/ideias'){
      const c=client(fields.clientId);if(!c)return notFound(res);c.contentLastIdeas=generateIdeas(c,fields);c.contentLastIdeas[0].product=fields.product||metrics(c).hero?.name||'produto principal';save();return redirect(res,`/conteudo?client=${c.id}`);
    }
    if(req.method==='POST'&&url.pathname==='/conteudo/roteiro'){
      const c=client(fields.clientId);if(!c)return notFound(res);c.contentLastScript=buildScript(fields);save();return redirect(res,`/conteudo?client=${c.id}`);
    }
    if(req.method==='POST'&&url.pathname==='/campanhas/criar'){
      const p=pendingCampaigns.get(fields.token);if(!p)return redirect(res,'/campanhas/nova');const c=client(p.clientId),account=(c?.adAccounts||[]).find(a=>a.id===p.accountId);if(!c||!account)return redirect(res,'/campanhas/nova');const camp={id:id(),clientId:c.id,clientName:c.name,accountId:account.id,platform:account.platform,name:p.name,objective:p.objective,budgetDaily:num(p.budgetDaily),budgetTotal:num(p.budgetTotal),startDate:p.startDate,endDate:p.endDate,audience:p.audience,location:p.location,age:p.age,gender:p.gender,placements:p.placements,conversionEvent:p.conversionEvent,status:'Pausada',mode:'local',createdAt:new Date().toISOString()};db.campaigns.push(camp);if(p.creativeData){db.creatives.push({...p.creativeData,clientId:c.id,clientName:c.name,campaignId:camp.id,campaignName:camp.name,primaryText:p.primaryText,headline:p.headline,description:p.description,cta:p.cta,destinationUrl:p.destinationUrl,utm:p.utm});}pendingCampaigns.delete(fields.token);save();return redirect(res,`/campanhas/${camp.id}`);
    }
    if(req.method==='POST'&&url.pathname==='/importar'){
      const c=client(fields.client);if(!c)return notFound(res); const file=files.find(x=>x.field==='file');if(!file)return redirect(res,`/importar?client=${c.id}`);const lower=file.name.toLowerCase();
      if(lower.endsWith('.csv')||lower.endsWith('.xlsx')){const data=lower.endsWith('.xlsx')?xlsx(file.data):csv(file.data.toString('utf8'));const token=id();pendingImports.set(token,{clientId:c.id,name:file.name,type:fields.type||'Dados',period:fields.period||'',headers:data.headers,rows:data.rows,preview:data.rows.slice(0,3),map:autoMapping(data.headers)});return redirect(res,`/importar/confirmar?token=${token}`);}
      c.imports.push({id:id(),name:file.name,type:fields.type||'Dados',period:fields.period||'',status:'Arquivo registrado para revisão manual',uploadedAt:new Date().toISOString()});save();return redirect(res,`/importar?client=${c.id}`);
    }
    if(req.method==='POST'&&url.pathname==='/importar/confirmar'){
      const p=pendingImports.get(fields.token);if(!p)return redirect(res,'/importar');const c=client(p.clientId);if(!c)return notFound(res);const map=p.headers.map((_,i)=>fields[`m_${i}`]||'IGNORE');const added=applyProducts(c,p.rows,p.headers,map);c.imports.push({id:id(),name:p.name,type:p.type,period:p.period,status:added?`${added} linha(s) normalizada(s) para produtos`:'Importado, mas sem produtos identificados',uploadedAt:new Date().toISOString()});pendingImports.delete(fields.token);save();return redirect(res,`/cardapio?client=${c.id}`);
    }
    return notFound(res);
  }catch(error){console.error(error);html(res,page('Não foi possível concluir','',`<section class="card"><h2>O arquivo não foi processado</h2><p class="sub">${esc(error.message||'Erro inesperado.')}</p><a class="btn" href="javascript:history.back()">Voltar</a></section>`),400);}
}).listen(PORT,'0.0.0.0',()=>console.log(`Sistema Decola unificado em http://127.0.0.1:${PORT}`));
